  tbody.innerHTML=users.map(item=>`<tr><td><strong>${escapeHtml(item.name)}</strong>${item.id===currentUser.id?' <span class="muted-small">(você)</span>':''}</td><td>${escapeHtml(item.email)}</td><td>${roleName(item.role)}</td><td><span class="status-pill ${item.active?'':'low'}">${item.active?'Ativo':'Inativo'}</span></td><td>${new Date(`${item.created_at.replace(' ','T')}Z`).toLocaleDateString('pt-BR')}</td><td>${item.id===currentUser.id?'—':`<button class="table-action" data-user-id="${item.id}" data-active="${!item.active}">${item.active?'Desativar':'Reativar'}</button>`}</td></tr>`).join('');
  view.querySelector('#audit-link').onclick=()=>setRoute('auditoria');
  view.querySelector('#new-user').onclick=()=>openDialog('Novo usuário','Cada pessoa acessa o sistema com a própria conta.',[field('Nome','name',{required:true,wide:true}),field('E-mail','email',{type:'email',required:true,wide:true}),field('Perfil','role',{options:[['manager','Gerente'],['owner','Proprietário']]}),field('Senha inicial','password',{type:'password',required:true,placeholder:'Mínimo 12 caracteres'})],'Criar usuário',async data=>{if(data.password.length<12)throw new Error('A senha deve ter pelo menos 12 caracteres.');await request('/api/users',{method:'POST',body:JSON.stringify(data)});});
  tbody.onclick=async event=>{const button=event.target.closest('[data-user-id]');if(!button)return;const active=button.dataset.active==='true';if(!window.confirm(`${active?'Reativar':'Desativar'} este acesso? O histórico permanecerá no sistema.`))return;try{await request(`/api/users/${button.dataset.userId}`,{method:'PATCH',body:JSON.stringify({active})});await showAdmin('usuarios');notify('Acesso atualizado.');}catch(e){notify(e.message);}};
