const todayLocal=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
async function showSales() {
  const view=document.querySelector('#view');view.innerHTML=pageHead('COMERCIAL','Vendas','Registre vendas, acompanhe pagamentos e gere recibos.','<button class="outline-button" id="sales-customers">＋ Novo cliente</button><button class="button button-primary" id="sales-new">＋ Nova venda</button>')+`<section class="table-card"><div class="table-toolbar"><input class="table-search" type="search" placeholder="Pesquisar número ou cliente…"><span class="record-count"></span></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Venda</th><th>Data</th><th>Cliente</th><th>Total</th><th>Recebido</th><th>Situação</th><th>Ações</th></tr></thead><tbody></tbody></table></div><div class="pagination"></div></section>`;
  try{const [sales,customers,products]=await Promise.all([request('/api/sales'),request('/api/customers'),request('/api/products')]);catalogItems=sales.items;const clients=customers.items.filter(item=>item.active),models=products.items.filter(item=>item.active);drawSalesTable(view,catalogItems);view.querySelector('#sales-customers').onclick=()=>setRoute('clientes');view.querySelector('#sales-new').onclick=()=>openSaleDialog(clients,models);}
  catch(e){view.querySelector('tbody').innerHTML=`<tr><td class="table-empty" colspan="7">${escapeHtml(e.message)}</td></tr>`;}
}
function drawSalesTable(view,sales) {
  const tbody=view.querySelector('tbody'),search=view.querySelector('.table-search'),count=view.querySelector('.record-count'),pager=view.querySelector('.pagination');let page=0;const pageSize=20;
  function draw(){const term=search.value.trim().toLocaleLowerCase('pt-BR'),items=sales.filter(s=>`${s.number} ${s.customer_name||''}`.toLocaleLowerCase('pt-BR').includes(term)),pages=Math.max(1,Math.ceil(items.length/pageSize));page=Math.min(page,pages-1);count.textContent=`${items.length} ${items.length===1?'venda':'vendas'}`;tbody.innerHTML=items.length?items.slice(page*pageSize,(page+1)*pageSize).map(s=>{const pending=s.total_cents-s.received_cents;return `<tr><td><strong>${escapeHtml(s.number)}</strong>${s.historical?' <span class="muted-small">Histórica</span>':''}</td><td>${new Date(`${s.sale_date}T00:00:00`).toLocaleDateString('pt-BR')}</td><td>${escapeHtml(s.customer_name||'Venda avulsa')}</td><td>${money(s.total_cents)}</td><td>${money(s.received_cents)}</td><td><span class="status-pill ${s.status==='cancelled'?'low':''}">${s.status==='paid'?'Paga':s.status==='cancelled'?'Cancelada':`Pendente ${money(pending)}`}</span></td><td><button class="table-action" data-sale-action="receipt" data-id="${s.id}">Recibo</button>${s.status==='open'?` · <button class="table-action" data-sale-action="pay" data-id="${s.id}">Receber</button>`:''}${s.status!=='cancelled'&&s.received_cents===0?` · <button class="table-action" data-sale-action="cancel" data-id="${s.id}">Cancelar</button>`:''}</td></tr>`;}).join(''):`<tr><td colspan="7" class="table-empty">${term?'Nenhuma venda encontrada.':'Ainda não há vendas registradas.'}</td></tr>`;pager.innerHTML=pages>1?`<button data-page="prev" ${page===0?'disabled':''}>Anterior</button><span>Página ${page+1} de ${pages}</span><button data-page="next" ${page+1===pages?'disabled':''}>Próxima</button>`:'';}
  draw();search.oninput=()=>{page=0;draw();};pager.onclick=e=>{if(e.target.dataset.page==='prev')page--;if(e.target.dataset.page==='next')page++;draw();};
  tbody.onclick=async e=>{const b=e.target.closest('[data-sale-action]');if(!b)return;const sale=sales.find(s=>s.id===b.dataset.id);if(!sale)return;if(b.dataset.saleAction==='receipt'){window.receiptSale=sale.id;setRoute('recibos');return;}if(b.dataset.saleAction==='pay'){openPaymentDialog(`/api/sales/${sale.id}/payments`,sale.total_cents-sale.received_cents,data=>request(`/api/sales/${sale.id}/payments`,{method:'POST',body:JSON.stringify(data)}));return;}if(b.dataset.saleAction==='cancel'){const reason=window.prompt('Informe o motivo do cancelamento:');if(!reason)return;try{await request(`/api/sales/${sale.id}/cancel`,{method:'POST',body:JSON.stringify({reason})});await showSales();notify('Venda cancelada.');}catch(err){notify(err.message);}}};
}
function openSaleDialog(customers,products) {
  const dialog=document.querySelector('#record-dialog'),productOptions=products.map(p=>`<option value="${p.id}" data-price="${p.price_cents}" data-name="${escapeHtml(p.name)}" data-sku="${escapeHtml(p.sku)}">${escapeHtml(p.name)} · ${escapeHtml(p.sku)}</option>`).join('');
  dialog.innerHTML=`<header class="dialog-head"><div><h2>Nova venda</h2><p>Valores e produtos serão copiados para o histórico desta venda.</p></div><button class="dialog-close" type="button">×</button></header><form class="dialog-form sale-form"><label>Cliente<select name="customerId" required><option value="">Selecione um cliente</option>${customers.map(c=>`<option value="${c.id}">${escapeHtml(c.name)}</option>`).join('')}</select></label><label>Data da venda<input name="saleDate" type="date" value="${todayLocal()}" required></label><label>Vencimento<input name="dueDate" type="date"></label><label>Desconto total (R$)<input name="discount" type="number" min="0" step="0.01" value="0"></label><div class="sale-items-wrap wide"><div class="sale-items-head"><strong>Itens da venda</strong><button type="button" class="table-action" id="add-sale-item">＋ Adicionar item</button></div><div class="sale-items"></div></div><label class="historical-check wide"><input name="historical" type="checkbox"> Esta é uma venda anterior à implantação do sistema</label><label>Valor já recebido (R$)<input name="initialReceived" type="number" min="0" step="0.01" value="0"></label><label>Forma de pagamento<select name="paymentMethod"><option>PIX</option><option>Dinheiro</option><option>Cartão</option><option>Transferência</option><option>Boleto</option><option>Outro</option></select></label><label class="wide">Observações<textarea name="notes"></textarea></label><div class="sale-total wide"><span>Total da venda</span><strong id="sale-total">R$ 0,00</strong></div><div class="dialog-actions"><button class="outline-button dialog-cancel" type="button">Cancelar</button><button class="button button-primary" type="submit">Registrar venda</button></div></form>`;
  const form=dialog.querySelector('form'),rows=dialog.querySelector('.sale-items');
  function addRow(){const row=document.createElement('div');row.className='sale-item-row';row.innerHTML=`<select data-product><option value="">Item avulso</option>${productOptions}</select><input data-name placeholder="Nome / modelo" aria-label="Nome do produto"><input data-quantity type="number" min="0.001" step="0.001" value="1" aria-label="Quantidade"><input data-price type="number" min="0" step="0.01" placeholder="Preço unitário" aria-label="Preço unitário"><input data-color placeholder="Cor / variação" aria-label="Cor ou variação"><button type="button" class="remove-line" aria-label="Remover item">×</button>`;rows.append(row);row.querySelector('[data-product]').onchange=e=>{const option=e.target.selectedOptions[0];if(!e.target.value){row.querySelector('[data-name]').value='';row.querySelector('[data-price]').value='';delete row.dataset.sku;updateTotal();return;}row.querySelector('[data-name]').value=option.dataset.name;row.querySelector('[data-price]').value=(Number(option.dataset.price)/100).toFixed(2);row.dataset.sku=option.dataset.sku;updateTotal();};row.querySelector('.remove-line').onclick=()=>{row.remove();updateTotal();};row.addEventListener('input',updateTotal);}
  function updateTotal(){let subtotal=0;for(const row of rows.children)subtotal+=Math.round(Number(row.querySelector('[data-quantity]').value||0)*Number(row.querySelector('[data-price]').value||0)*100);const discount=Math.round(Number(form.elements.discount.value||0)*100);dialog.querySelector('#sale-total').textContent=money(Math.max(0,subtotal-discount));}
  addRow();dialog.querySelector('#add-sale-item').onclick=addRow;form.addEventListener('input',updateTotal);dialog.querySelector('.dialog-close').onclick=()=>dialog.close();dialog.querySelector('.dialog-cancel').onclick=()=>dialog.close();
  form.elements.historical.onchange=()=>{const label=form.elements.initialReceived.closest('label');label.firstChild.textContent=form.elements.historical.checked?'Já recebido antes do sistema (não afeta caixa)':'Valor já recebido (R$)';};
  form.onsubmit=async event=>{event.preventDefault();const button=form.querySelector('[type=submit]'),items=[...rows.children].map(row=>({productId:row.querySelector('[data-product]').value||null,name:row.querySelector('[data-name]').value,sku:row.dataset.sku||'',quantity:row.querySelector('[data-quantity]').value,unitPrice:row.querySelector('[data-price]').value,color:row.querySelector('[data-color]').value}));if(!items.length||items.some(item=>!item.name)){notify('Informe pelo menos um item e seu nome.');return;}button.disabled=true;try{await request('/api/sales',{method:'POST',body:JSON.stringify({requestKey:crypto.randomUUID(),customerId:form.elements.customerId.value,saleDate:form.elements.saleDate.value,dueDate:form.elements.dueDate.value,historical:form.elements.historical.checked,initialReceived:form.elements.initialReceived.value,paymentMethod:form.elements.paymentMethod.value,discount:form.elements.discount.value,notes:form.elements.notes.value,items})});dialog.close();await showSales();notify('Venda registrada.');}catch(e){notify(e.message);button.disabled=false;}};
  dialog.showModal();
}
