async function openProductionCompletion(order) {
  const [{items:bom},{items:materials},defaults]=await Promise.all([request(`/api/products/${order.product_id}/materials`),request('/api/materials'),request('/api/production/defaults')]);
  const dialog=document.querySelector('#record-dialog'),available=materials.filter(m=>m.active),materialOptions=available.map(m=>`<option value="${m.id}" data-unit="${escapeHtml(m.unit)}" data-per-unit="${bom.find(x=>x.material_id===m.id)?.quantity_per_unit||''}">${escapeHtml(m.name)} · saldo ${quantity(m.quantity)} ${escapeHtml(m.unit)}</option>`).join('');
  dialog.innerHTML=`<header class="dialog-head"><div><h2>Concluir ${escapeHtml(order.number)}</h2><p>O sistema vai baixar os consumos e adicionar as unidades aprovadas ao estoque.</p></div><button class="dialog-close">×</button></header><form class="dialog-form production-complete"><label>Data de conclusão<input name="completedDate" type="date" value="${todayLocal()}" required></label><label>Quantidade produzida<input name="producedQuantity" type="number" min="0.001" step="0.001" value="${order.planned_quantity}" required></label><label>Aprovadas<input name="approvedQuantity" type="number" min="0" step="0.001" value="${order.planned_quantity}" required></label><label>Defeituosas / perdidas<input name="defectiveQuantity" type="number" min="0" step="0.001" value="0" required></label><label>Custo de mão de obra total (R$)<input name="laborCost" type="number" min="0" step="0.01" value="${(defaults.labor_cost_per_bag_cents*order.planned_quantity/100).toFixed(2)}" required></label><label>Custo adicional total (R$)<input name="additionalCost" type="number" min="0" step="0.01" value="0" required></label><div class="bom-rows wide"></div><button type="button" class="outline-button wide" id="consumption-add">＋ Informar material consumido</button><p class="wide production-note">Materiais da ficha técnica serão sugeridos conforme a quantidade produzida. Você pode ajustar o consumo real.</p><div class="dialog-actions"><button type="button" class="outline-button dialog-cancel">Voltar</button><button type="submit" class="button button-primary">Concluir produção</button></div></form>`;
  const rows=dialog.querySelector('.bom-rows');function addConsumption(item={}){const row=document.createElement('div');row.className='bom-row';row.innerHTML=`<select required><option value="">Material</option>${materialOptions}</select><input type="number" min="0.0001" step="0.0001" required placeholder="Qtd. consumida"><button type="button" class="remove-line">×</button>`;row.querySelector('select').value=item.material_id||'';row.querySelector('input').value=item.quantity||'';row.querySelector('.remove-line').onclick=()=>row.remove();rows.append(row);}
  if(bom.length)bom.forEach(m=>addConsumption({material_id:m.material_id,quantity:(m.quantity_per_unit*order.planned_quantity).toFixed(3)}));
  dialog.querySelector('#consumption-add').onclick=()=>addConsumption();dialog.querySelector('.dialog-close').onclick=()=>dialog.close();dialog.querySelector('.dialog-cancel').onclick=()=>dialog.close();
  const form=dialog.querySelector('form'),produced=form.elements.producedQuantity;let last=Number(produced.value);produced.oninput=()=>{const next=Number(produced.value);for(const row of rows.children){const option=row.querySelector('select').selectedOptions[0],per=Number(option.dataset.perUnit);if(per&&Number(row.querySelector('input').value)===per*last)row.querySelector('input').value=(per*next).toFixed(3);}last=next;};
  form.onsubmit=async e=>{e.preventDefault();const submit=form.querySelector('[type=submit]'),approved=Number(form.elements.approvedQuantity.value),defective=Number(form.elements.defectiveQuantity.value);if(Math.abs(approved+defective-Number(produced.value))>.0001){notify('Produzidas deve ser igual a aprovadas mais defeituosas.');return;}submit.disabled=true;try{const consumptions=[...rows.children].map(row=>({materialId:row.querySelector('select').value,quantity:Number(row.querySelector('input').value)}));if(consumptions.some(x=>!x.materialId||x.quantity<=0))throw new Error('Confira as quantidades de materiais consumidos.');await request(`/api/production/${order.id}`,{method:'PATCH',body:JSON.stringify({status:'completed',completedDate:form.elements.completedDate.value,producedQuantity:Number(produced.value),approvedQuantity:approved,defectiveQuantity:defective,laborCost:Number(form.elements.laborCost.value),additionalCost:Number(form.elements.additionalCost.value),consumptions})});dialog.close();await showProduction();notify('Produção concluída; estoque e custos foram atualizados.');}catch(err){notify(err.message);submit.disabled=false;}};dialog.showModal();
}
